        </div>

        <h2 class="logout-sheet__title">Вы действительно хотите<br>выйти из приложения?</h2>
        <p class="logout-sheet__desc">При выходе из профиля приложения необходимо будет повторно установить короткий код доступа, FaceID/TouchID.</p>

        <div class="logout-sheet__actions">
          <button class="logout-sheet__btn logout-sheet__btn--cancel" @click="$emit('update:modelValue', false)">
            Отменить
          </button>
          <button class="logout-sheet__btn logout-sheet__btn--confirm" @click="onConfirm">
            Да, выйти
          </button>
        </div>
      </div>
    </transition>
  </teleport>
</template>

<script setup>
import { useRouter } from 'vue-router'

const props = defineProps({
  modelValue: Boolean
})

const emit = defineEmits(['update:modelValue'])
const router = useRouter()

const onConfirm = () => {
  emit('update:modelValue', false)
  // clear auth state
  localStorage.removeItem('userPin')
  localStorage.removeItem('authToken')
  router.replace({ name: 'profile-unauthorized' }) // profile will render unauthorized state
}

</script>

